/**
 * poi-marker-art.ts -- DS POI category marker artwork (Figma 555:69603/555:69751).
 *
 * Source: assets/icons/poi/*.svg -- 16 category markers, each a 48x69
 * teardrop pin (colored squircle head, white glyph, dot foot). Embedded
 * as data URIs (same convention as VehicleIcon3D weather-station-art.ts)
 * so PoiMarker/PoiCategoryChip ship with zero external asset requests and
 * no bundler SVG loader is required (tsup.config.ts has none configured).
 * Regenerate against assets/icons/poi/*.svg if the designer refreshes an export.
 */

export interface PoiCategoryArt {
  id: string
  label: string
  /** Squircle-head fill color sampled from the source SVG (CSS color or hex). */
  color: string
  /** data: URI of the full 48x69 teardrop marker SVG. */
  src: string
}

/** Native marker aspect (Figma 555:69603 export, viewBox 0 0 48 69). */
export const POI_MARKER_WIDTH = 48
export const POI_MARKER_HEIGHT = 69

